function inlineUrineGallery(){if(selected!==3||index!==5)return '';return '<h3 style="font-size:14px">🔬 Authentic urine sediment photographs</h3><p style="font-size:12px">Images from Cornell eClinPath correspond to the urine sediment portion of the uploaded 2025 Urinalysis lecture (slides 27–45). Tap an image to read its morphology, mechanism and interpretation in the microscope atlas.</p><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:8px">'+urinePhotoExamples.map(p=>'<button data-cpg-image="'+esc(p[2])+'" style="white-space:normal;padding:8px;text-align:center"><img src="'+esc(p[1])+'" alt="Authentic urine sediment specimen" loading="lazy" style="width:100%;height:112px;object-fit:contain;background:#eaf2fb;border-radius:7px" onerror="this.hidden=true"><small style="display:block;margin-top:5px">'+esc(p[0])+'</small></button>').join('')+'</div><p style="font-size:11px">Source: <a href="https://eclinpath.com/atlas/urinalysis/" target="_blank" rel="noopener noreferrer">Cornell eClinPath Urinalysis atlas</a> and <a href="https://eclinpath.com/urinalysis/casts/" target="_blank" rel="noopener noreferrer">cast identification</a>.</p>'}
function teachingPanel(){const k=selected+':'+index,rows=detailedTeaching[k]||[],links=atlasLinks[k]||[];return '<section style="margin:12px 0;padding:10px;background:#f6faff;border:1px solid #cbdced;border-radius:12px"><b>📚 Lecture depth · worked reasoning</b><table style="width:100%;border-collapse:collapse;font-size:12px">'+rows.map(r=>'<tr><th style="padding:7px;text-align:left;vertical-align:top;border-bottom:1px solid #dae4f1">'+esc(r[0])+'</th><td style="padding:7px;border-bottom:1px solid #dae4f1">'+esc(r[1])+'</td></tr>').join('')+'</table>'+(links.length?'<p><b>Related microscope findings (open directly):</b></p>'+links.map(id=>'<button style="font-size:12px;margin:3px" data-cpg-image="'+id+'">🔬 '+esc(window.VPQ_CLINPATH_VISUAL_ATLAS?.entries?.find(e=>e.id===id)?.name||id)+'</button>').join(''):'')+inlineUrineGallery()+'<p style="font-size:11px">Use species- and laboratory-specific reference intervals. These are instruction examples, not patient treatment thresholds.</p></section>'}


